
/* ---------- sparkle + star field ---------- */
(function(){
  var wrap = document.getElementById('sparkles');
  if (!wrap) return;
  var mobile = window.innerWidth < 600;
  var dots = mobile ? 30 : 54;
  for (var i = 0; i < dots; i++) {
    var s = document.createElement('div');
    var r = Math.random();
    s.className = 'sp' + (r > .82 ? ' big' : '') + (Math.random() > .55 ? ' rose' : '');
    s.style.left = (Math.random() * 100) + '%';
    s.style.top = (100 + Math.random() * 30) + '%';
    s.style.animationDuration = (14 + Math.random() * 18) + 's';
    s.style.animationDelay = (-Math.random() * 30) + 's';
    wrap.appendChild(s);
  }
  var stars = mobile ? 6 : 12;
  for (var j = 0; j < stars; j++) {
    var st = document.createElement('div');
    st.className = 'star';
    var sz = 8 + Math.random() * 12;
    st.style.width = sz + 'px';
    st.style.height = sz + 'px';
    st.style.left = (Math.random() * 100) + '%';
    st.style.top = (Math.random() * 100) + '%';
    st.style.animationDuration = (3.5 + Math.random() * 4.5) + 's';
    st.style.animationDelay = (-Math.random() * 8) + 's';
    wrap.appendChild(st);
  }
})();

