/* ---------- engine ---------- */
var cur = 0;
var answers = [];
var busy = false;

function show(id){
  var all = document.querySelectorAll('.screen');
  for (var i = 0; i < all.length; i++) all[i].classList.remove('active');
  document.getElementById(id).classList.add('active');
  if (window.scrollTo) window.scrollTo({top:0, behavior:'auto'});
}

function bar(){
  document.getElementById('bar').style.width = (cur / questions.length * 100) + '%';
}

function start(){
  cur = 0;
  busy = false;
  answers = [];
  for (var i = 0; i < questions.length; i++) answers.push(null);
  render();
  show('quiz');
}

function render(){
  var q = questions[cur];
  document.getElementById('qnum').textContent =
    ('0' + (cur + 1)).slice(-2) + ' / ' + questions.length;
  document.getElementById('qtext').textContent = q.t;

  var list = document.getElementById('opts');
  list.innerHTML = '';
  for (var i = 0; i < q.o.length; i++) {
    (function(idx){
      var li = document.createElement('li');
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'opt';
      b.textContent = q.o[idx][0];
      if (answers[cur] === idx) b.className += ' picked';
      b.onclick = function(){ pick(idx); };
      li.appendChild(b);
      list.appendChild(li);
    })(i);
  }

  document.getElementById('back').disabled = (cur === 0);
  bar();
}

function pick(i){
  if (busy) return;
  busy = true;
  answers[cur] = i;

  var btns = document.getElementById('opts').getElementsByTagName('button');
  for (var k = 0; k < btns.length; k++) {
    btns[k].className = 'opt' + (k === i ? ' picked' : '');
  }

  setTimeout(function(){
    busy = false;
    if (cur < questions.length - 1) {
      cur++;
      render();
    } else {
      finish();
    }
  }, 430);
}

function prev(){
  if (busy || cur === 0) return;
  cur--;
  render();
}

function finish(){
  var scores = [0,0,0,0,0,0];
  for (var q = 0; q < answers.length; q++) {
    var a = answers[q];
    if (a === null) continue;
    var s = questions[q].o[a][1];
    for (var t = 0; t < 6; t++) scores[t] += s[t];
  }

  show('load');
  document.getElementById('bar').style.width = '100%';

  setTimeout(function(){ reveal(scores); }, 2100);
}

function reveal(scores){
  var order = [];
  for (var i = 0; i < 6; i++) order.push({v:scores[i], i:i});
  order.sort(function(a,b){ return b.v - a.v; });

  var top = order[0];
  var second = order[1];
  var r = results[top.i];

  document.getElementById('resimg').src = r.img;
  document.getElementById('resimg').alt = r.title;
  document.getElementById('restitle').textContent = r.title;
  document.getElementById('resbody').innerHTML = r.body;
  document.getElementById('reshint').textContent = r.hint;

  var also = document.getElementById('also');
  if (second.v >= 3 && second.v >= top.v - 3) {
    also.textContent = 'Silně se u vás projevuje také ' + alsoLabels[second.i] + '.';
    also.style.display = 'block';
  } else {
    also.style.display = 'none';
  }

  show('result');
}

/* ---------- Tilda iframe auto-height bridge ---------- */
(function () {
  var MESSAGE_TYPE = 'purposeQuizHeight';
  var REQUEST_TYPE = 'purposeQuizRequestHeight';
  var rafId = null;

  function getDocumentHeight() {
    var body = document.body;
    var html = document.documentElement;

    return Math.ceil(Math.max(
      body ? body.scrollHeight : 0,
      body ? body.offsetHeight : 0,
      body ? body.clientHeight : 0,
      html ? html.scrollHeight : 0,
      html ? html.offsetHeight : 0,
      html ? html.clientHeight : 0
    ));
  }

  function sendHeight() {
    if (window.parent === window) return;

    if (rafId) cancelAnimationFrame(rafId);
    rafId = requestAnimationFrame(function () {
      window.parent.postMessage({
        type: MESSAGE_TYPE,
        height: getDocumentHeight()
      }, '*');
    });
  }

  function sendSeveralTimes() {
    sendHeight();
    setTimeout(sendHeight, 100);
    setTimeout(sendHeight, 300);
    setTimeout(sendHeight, 700);
    setTimeout(sendHeight, 1400);
    setTimeout(sendHeight, 2400);
  }

  window.addEventListener('load', sendSeveralTimes);
  window.addEventListener('resize', sendSeveralTimes);
  window.addEventListener('orientationchange', sendSeveralTimes);

  window.addEventListener('message', function (event) {
    if (event.data && event.data.type === REQUEST_TYPE) {
      sendSeveralTimes();
    }
  });

  if ('ResizeObserver' in window) {
    var resizeObserver = new ResizeObserver(sendHeight);
    resizeObserver.observe(document.documentElement);
    if (document.body) resizeObserver.observe(document.body);
  }

  if ('MutationObserver' in window && document.body) {
    var mutationObserver = new MutationObserver(sendSeveralTimes);
    mutationObserver.observe(document.body, {
      subtree: true,
      childList: true,
      attributes: true,
      characterData: true
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var images = document.images || [];
    for (var i = 0; i < images.length; i++) {
      images[i].addEventListener('load', sendSeveralTimes);
      images[i].addEventListener('error', sendSeveralTimes);
    }
    sendSeveralTimes();
  });

  document.addEventListener('click', function () {
    sendSeveralTimes();
  }, true);
})();
